        return $rows[0] ?? null;
    }

    // -- name: EchoAuthorIDText :one
    public function echoAuthorIdtext(string $authorId): ?EchoAuthorIdtextRow
    {
        $parameters = [
            '$author_id' => YdbValueCodec::typedUtf8($authorId, 'author_id'),
        ];

        $result = $this->execute(function (Session $session) use ($parameters): ExecuteQueryResult {
            $query = $session->newQuery(<<<'SQLC_YDB_YQL'
                SELECT $author_id AS author_id_text;
                SQLC_YDB_YQL)
                ->parameters($parameters)
                ->keepInCache(count($parameters) > 0);
            if ($this->txId !== null) {
                $query->txControl(new TransactionControl(['tx_id' => $this->txId]));
                $txControl = $query->getRequestData()['tx_control']->serializeToString();
            } else {
                $query->beginTx('serializable_read_write');
            }
            if ($this->configure !== null) {
                ($this->configure)($query);
            }
            if ($this->txId !== null && $query->getRequestData()['tx_control']->serializeToString() !== $txControl) {
                throw new \LogicException('configure must not change transaction control on a transaction-bound Queries');
            }

            return (new YdbRawExecutor($this->table))->execute($session, $query, $this->txId === null);
        });

        $rows = $this->decodeRows(
            $result,
            'EchoAuthorIDText',
            [
                ['author_id_text', PrimitiveTypeId::UTF8, false],
            ],
            static fn($items): EchoAuthorIdtextRow => new EchoAuthorIdtextRow(
                YdbValueCodec::utf8($items->offsetGet(0), 'EchoAuthorIDText.author_id_text'),
            ),
        );

        return $rows[0] ?? null;
    }

    /**
     * @param array<int, array{0: string, 1: int, 2: bool}> $expectedColumns
     * @return list<object>
     */
    private function decodeRows(ExecuteQueryResult $result, string $query, array $expectedColumns, Closure $decode): array
    {
        $sets = $result->getResultSets();
        if (count($sets) !== 1) {
            throw new UnexpectedValueException(sprintf('%s: expected one YDB result set, got %d', $query, count($sets)));
        }
        $set = $sets->offsetGet(0);
        if ($set->getTruncated()) {
            throw new UnexpectedValueException($query . ': YDB result is truncated; use a bounded query or pagination');
        }

        $columns = $set->getColumns();
        if (count($columns) !== count($expectedColumns)) {
            throw new UnexpectedValueException(sprintf('%s: expected %d result columns, got %d', $query, count($expectedColumns), count($columns)));
        }
        foreach ($expectedColumns as $index => [$name, $typeId, $optional]) {
            $column = $columns->offsetGet($index);
            if ($column->getName() !== $name) {
                throw new UnexpectedValueException(sprintf('%s: result column %d is %s, expected %s', $query, $index, $column->getName(), $name));
            }
            YdbValueCodec::assertType($column->getType(), $typeId, $optional, $query . '.' . $name);
        }
        $rows = [];
        foreach ($set->getRows() as $rowIndex => $row) {
            $items = $row->getItems();
            if (count($items) !== count($expectedColumns)) {
                throw new UnexpectedValueException(sprintf('%s: row %d has %d values, expected %d', $query, $rowIndex, count($items), count($expectedColumns)));
            }
            $rows[] = $decode($items);
        }
        return $rows;
    }
